    mains = [c for c in cards if c.get('main')]
    all_names = []
    for c in mains:
        if label(c) not in all_names:
            all_names.append(label(c))
    matches = []
    if kind != 'all':
        if len(digits) >= 4:
            cand = pool if stage != 'name' else list(range(len(cards)))
            if len(digits) >= 10:
                matches = [i for i in cand if cards[i]['num'][:6] == digits[:6] and cards[i]['l4'] == digits[-4:]]
