            else:
                matches = [i for i in cand if cards[i]['l4'] == digits[-4:]]
        elif name:
            cand = pool if stage != 'name' else list(range(len(cards)))
            matches = [i for i in cand if norm(cards[i]['name']) == name]
            if not matches:
                cont = [i for i in cand if cards[i]['name'] and norm(cards[i]['name']) in name]
                if cont:
                    longest = max(len(norm(cards[i]['name'])) for i in cont)
                    matches = [i for i in cont if len(norm(cards[i]['name'])) == longest]
                else:
                    matches = [i for i in cand if cards[i]['name'] and name in norm(cards[i]['name'])]
    vars['select_state'] = 'ask'
    if kind == 'all':
        tries += 1
        vars['select_prompt'] = q
    elif len(matches) == 1:
        c = cards[matches[0]]
        if not c.get('main'):
            vars['select_prompt'] = 'Bu kart için ekstre borcu sorgulayabileceğiniz uygun bir kart bulunmuyor. Lütfen başka bir kartınızı seçin. ' + q
            vars['select_stage'] = 'name'
            vars['select_pool'] = '[]'
        else:
            vars['sel_card'] = c['num']
            vars['sel_name'] = c['name']
            vars['sel_l4'] = c['l4']
            vars['select_state'] = 'chosen'
    elif len(matches) > 1:
        ms = [cards[i] for i in matches]
        vars['select_pool'] = json.dumps(matches)
        same_name = len(set(c['name'] for c in ms)) == 1
        same_l4 = len(set(c['l4'] for c in ms)) == 1
        if same_l4 and len(digits) >= 6:
            vars['select_stage'] = 'full'
            vars['select_prompt'] = 'Son altı hanesi aynı olan birden fazla kartınız var. Kart numaranızı söyler misiniz?'
        elif same_l4 and len(digits) >= 4:
            vars['select_stage'] = 'last6'
            vars['select_prompt'] = 'Son dört hanesi ' + ' '.join(DIG[int(ch)] for ch in ms[0]['l4'] if ch.isdigit()) + ' olan birden fazla kartınız var. Kartınızın son altı hanesini söyler misiniz?'
        elif same_name:
            vars['select_stage'] = 'last4'
            vars['select_prompt'] = (ms[0]['name'] or 'Bu') + ' isimli birden fazla kartınız var. Kartınızın son dört hanesini söyler misiniz?'
        else:
            vars['select_stage'] = 'name'
            vars['select_prompt'] = 'Bu tarife uyan kartlarınız: ' + ', '.join(label(c) for c in ms) + '. Hangisinin borcunu öğrenmek istersiniz?'
    else:
        tries += 1
        vars['select_stage'] = 'name'
        vars['select_pool'] = '[]'
        if digits:
            vars['select_prompt'] = 'Söylediğiniz numarayla eşleşen bir kartınız bulunmuyor. Kartınızın adını ya da son dört hanesini söyler misiniz?'
        else:
            vars['select_prompt'] = 'Bu isimde bir kartınız bulunmuyor. Kartlarınız: ' + ', '.join(all_names) + '. Hangi kartınızın borcunu öğrenmek istersiniz?'
    if vars['select_state'] != 'chosen' and tries >= 3:
        vars['select_state'] = 'tries'
    vars['select_tries'] = str(tries)
except Exception:
    vars['select_state'] = 'ask'
vars['select_kind'] = 'stay'
